.account-hub-view {
  display: grid;
  grid-template: "header" min-content "body" 1fr "footer" min-content;
  text-align: center;
  z-index: 1;
  max-block-size: 90vh;
  padding-inline: 20px;
  padding-block-start: 40px;
  border-radius: inherit;
  border: 1px solid var(--hub-border-color);
  /* Background color to better hide loading of the webp (>=100ms) */
  background-color: var(--color-surface-base);
  background-image: light-dark(url("chrome://messenger/skin/images/accounthub-bg-light.webp"), url("chrome://messenger/skin/images/accounthub-bg-dark.webp"));
  background-position: center center;
  background-repeat: no-repeat;
  background-size: cover;
